import{d as c,C as t,o as u,c as m,j as a,a as n,E as s,a3 as g}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第三十一章","description":"从兵器不祥、胜而不美与丧礼处之，理解战争中的克制与对死伤的哀悯。","frontmatter":{"title":"道德经第三十一章","description":"从兵器不祥、胜而不美与丧礼处之，理解战争中的克制与对死伤的哀悯。","category":"guide","aliases":["道德经第三十一章","老子第三十一章","dao de jing chapter 31"],"source":["王弼《道德真经注》卷二"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-31.md","filePath":"daoism/dao-de-jing/chapter-31.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-31.md"},_=c({...b,setup(p){const r=[{id:"weapons-as-inauspicious-instruments",label:"夫佳兵者，不祥之器",showLabel:!0,sentences:[["夫",{text:"佳兵",glossary:"jiabing"},"者，",{text:"不祥",glossary:"buxiang"},"之器，物或",{text:"恶",glossary:"wu"},"之，故有道者不",{text:"处",glossary:"chu"},"。"]],note:["【白话】精良的兵器也是不祥的器具，万物或厌恶它，所以有道的人不以此自处、不安于倚重兵器。开篇即从器物的用途与伤害审视武力。","【读法】佳兵本页先取精良兵器义；也有把佳理解为以兵为好、好兵的读法。两种取径都不宜将本句读成赞美武器。有道者不处的处读 chǔ，取安处义。"]},{id:"necessary-force-and-composure",label:"不得已而用之，恬淡为上",showLabel:!0,sentences:[["君子居则贵左，用兵则贵右。"],["兵者，不祥之器，非君子之器，",{text:"不得已",glossary:"budeyi"},"而用之，",{text:"恬淡",glossary:"tiandan"},"为上。"]],note:["【白话】君子平居尊左，用兵则尊右。兵器是不祥的器具，不是君子所崇尚之器；不得不用时，以恬静淡泊、不嗜杀争功为上。","【读法】左右的区别在下文吉事、凶事和丧礼中得到说明，是本章使用的礼制语境。恬淡约束用兵时的心态，不能被用作漠视受害者的理由；不得已也须连前章济难有止来读。"]},{id:"victory-without-glorifying-killing",label:"胜而不美",showLabel:!0,sentences:[["胜而不",{text:"美",glossary:"mei"},"，而美之者，是",{text:"乐",glossary:"le"},"杀人。"],["夫乐杀人者，则不可得志于天下矣。"]],note:["【白话】即使战胜，也不把它当作可夸耀的美事；把战胜美化为荣耀，就是以杀人为乐。以杀人为乐的人，不能在天下实现其志。","【读法】美在这里作以为美、赞美；乐作以之为乐，读 lè。此处所戒是对杀戮与胜利的迷恋，不是要求掩盖战事事实。"]},{id:"military-rank-and-mourning",label:"言以丧礼处之",showLabel:!0,sentences:[["吉事尚左，凶事尚右。"],[{text:"偏将军",glossary:"pianjiangjun"},"居左，",{text:"上将军",glossary:"shangjiangjun"},"居右，言以",{text:"丧礼",glossary:"sangli"},{text:"处",glossary:"chu-treat"},"之。"]],note:["【白话】吉庆之事尊左，凶丧之事尊右。副将居左，主将居右，这表明应以丧礼的态度对待用兵之事。","【读法】偏将军与上将军在这里用于说明军中主副和礼位，不据此概括历代官制。处之的处取对待、处理义，与开篇不处的安处义分开。"]},{id:"mourning-after-battle",label:"战胜，以丧礼处之",showLabel:!0,sentences:[["杀人众多，以悲哀泣之，战胜，以丧礼处之。"]],note:["【白话】杀死的人很多，应怀着悲哀为他们哭泣；即使打了胜仗，也应以丧礼对待。结尾把注意力重新放回死者与战争造成的损失。","【古注情况】本页所据卷二 008b 电子录文在本章未见独立的逐句王注。因此本页不将经文或本站解释题作王弼注；这也不等于已据此解决本章的传本或作者归属问题。"]}],i=[{id:"jiabing",term:"佳兵",sense:1},{id:"buxiang",term:"不祥",sense:1},{id:"wu",term:"恶",sense:1,pinyin:"wù"},{id:"chu",term:"处",sense:1},{id:"budeyi",term:"不得已",sense:2},{id:"tiandan",term:"恬淡",sense:1},{id:"mei",term:"美",sense:1},{id:"le",term:"乐",sense:1,pinyin:"lè"},{id:"pianjiangjun",term:"偏将军",sense:1},{id:"shangjiangjun",term:"上将军",sense:1},{id:"sangli",term:"丧礼",sense:1},{id:"chu-treat",term:"处",sense:2}];return(x,e)=>{const o=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),m("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第三十一章",tabindex:"-1"},[n("道德经第三十一章 "),a("a",{class:"header-anchor",href:"#道德经第三十一章","aria-label":'Permalink to "道德经第三十一章"'},"​")],-1)),s(o,{title:"战胜之后，为什么仍以丧礼处之",summary:"本章承接上章用兵有止，进一步把兵器、胜利与丧礼连在一起：必要时虽须用兵，也不可美化杀戮；结尾以悲哀对待死伤，使战争的代价始终在场。",points:[{label:"先读",text:"先辨不祥之器与不得已而用之，勿将用兵当作荣耀。"},{label:"再辨",text:"本章借左右的礼位区别平居、吉事与用兵、凶事。"},{label:"后看",text:"胜而不美连到悲哀泣之，胜负不能抹去众多生命的丧失。"}],hint:"恶读 wù；乐杀人的乐读 lè；丧礼的丧读 sāng。所据录文本章未见逐句王注，本页白话与解释另行标明。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[n("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),s(l,{sections:r,glossary:i}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[n("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),s(d,{lines:[{text:"兵者，不祥之器，非君子之器，不得已而用之，恬淡为上。",tone:"必要也有约束",guide:"不得已说明行动的限度，恬淡说明不能以好战、争功为取向。"},{text:"胜而不美，而美之者，是乐杀人。",tone:"胜利不能美化杀戮",guide:"将战果与对杀人的欣喜分开，警惕以荣耀遮蔽生命代价。"},{text:"杀人众多，以悲哀泣之，战胜，以丧礼处之。",tone:"把死伤放回眼前",guide:"丧礼与悲哀使战胜者也须面对损失，不以胜负取消哀悯。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[n("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(h,{items:i}),e[4]||(e[4]=g('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-为什么把兵器和丧礼写在同一章" tabindex="-1">象：为什么把兵器和丧礼写在同一章？ <a class="header-anchor" href="#象-为什么把兵器和丧礼写在同一章" aria-label="Permalink to &quot;象：为什么把兵器和丧礼写在同一章？&quot;">​</a></h3><p>本章先称兵为不祥之器，再借吉凶礼位说明军中主将居右，最后落到战胜仍以丧礼处之。礼制的对照让悲哀不是一句附带的感叹，而成为对用兵与战果的整体态度。</p><h3 id="理-不得已而用之-为什么仍须胜而不美" tabindex="-1">理：不得已而用之，为什么仍须胜而不美？ <a class="header-anchor" href="#理-不得已而用之-为什么仍须胜而不美" aria-label="Permalink to &quot;理：不得已而用之，为什么仍须胜而不美？&quot;">​</a></h3><p>必要行动与赞美杀戮是两个判断。即使确有不得已的处境，也不因此使死伤成为值得欣喜的事；若不断以胜利证明自己，便容易从解难滑向乐杀人。</p><h3 id="用-今天可以怎样借鉴这种态度" tabindex="-1">用：今天可以怎样借鉴这种态度？ <a class="header-anchor" href="#用-今天可以怎样借鉴这种态度" aria-label="Permalink to &quot;用：今天可以怎样借鉴这种态度？&quot;">​</a></h3><p>先保留本章的战争背景，再类比冲突之后的责任：记录受损者，处理后果，停止以羞辱对手制造新的敌意。日常争执与战争并不等量，但胜者仍须承担善后的提醒可以借鉴。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>让损失进入成果记录。</strong> 在处理冲突时，除了记录目标是否达到，也记录谁受了伤、哪些关系需要修复。庆祝解决了问题，不应变成庆祝对方受到伤害。</p><p><strong>为必要行动保留停止条件。</strong> 不能只凭不得已三个字便免去说明。应交代具体困境、替代办法与何时停止，并在事后检视是否扩大了冲突。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：当我取得一次胜利时，我最在意的是问题得到解决，还是对方被压倒？我愿意为这次冲突中的受损者做什么？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>本站保留「物或恶之」「恬淡」「则不可得志」「杀人众多」；所据 HFL 录文分别作「物惑恶之」「恬澹」「则不可以得志」「杀人之众」。这些差异逐项列明，不混改正文。</li><li>佳兵先取精良兵器义，另提示好兵的读法；美取以为美义。两处处字分安处与对待，乐杀人的乐读 lè。</li><li>所据录文本章未见逐句王注，本页不补造古注；左右仅依本章吉凶、军礼关系说明。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_002.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷二 HFL 本电子录文，008b</a>。</p>',15))])}}});export{y as __pageData,_ as default};
